export function ButterflyMark({
  width = 380,
  className,
}: {
  width?: number;
  className?: string;
}) {
  const height = width * 0.333333333333;

  return (
    <svg
      aria-label="Save Our Butterflies"
      role="img"
      width={width}
      height={height}
      viewBox="0 0 2172 724"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
    >
      <image
        href="data:image/png;base64,"
        x="0"
        y="0"
        width="2172"
        height="724"
        preserveAspectRatio="xMidYMid meet"
      />
    </svg>
  );
}
